        impl < 'a > Cursor < 'a > { pub fn new (input : & 'a str , frontmatter_allowed : FrontmatterAllowed) -> Cursor < 'a > { Cursor { len_remaining : input . len () , chars : input . chars () , frontmatter_allowed , # [cfg (debug_assertions)] prev : EOF_CHAR , } } pub fn as_str (& self) -> & 'a str { self . chars . as_str () } # [doc = " Returns the last eaten symbol (or `'\\0'` in release builds)."] # [doc = " (For debug assertions only.)"] pub (crate) fn prev (& self) -> char { # [cfg (debug_assertions)] { self . prev } # [cfg (not (debug_assertions))] { EOF_CHAR } } # [doc = " Peeks the next symbol from the input stream without consuming it."] # [doc = " If requested position doesn't exist, `EOF_CHAR` is returned."] # [doc = " However, getting `EOF_CHAR` doesn't always mean actual end of file,"] # [doc = " it should be checked with `is_eof` method."] pub fn first (& self) -> char { self . chars . clone () . next () . unwrap_or (EOF_CHAR) } # [doc = " Peeks the second symbol from the input stream without consuming it."] pub (crate) fn second (& self) -> char { let mut iter = self . chars . clone () ; iter . next () ; iter . next () . unwrap_or (EOF_CHAR) } # [doc = " Peeks the third symbol from the input stream without consuming it."] pub fn third (& self) -> char { let mut iter = self . chars . clone () ; iter . next () ; iter . next () ; iter . next () . unwrap_or (EOF_CHAR) } # [doc = " Checks if there is nothing more to consume."] pub (crate) fn is_eof (& self) -> bool { self . chars . as_str () . is_empty () } # [doc = " Returns amount of already consumed symbols."] pub (crate) fn pos_within_token (& self) -> u32 { (self . len_remaining - self . chars . as_str () . len ()) as u32 } # [doc = " Resets the number of bytes consumed to 0."] pub (crate) fn reset_pos_within_token (& mut self) { self . len_remaining = self . chars . as_str () . len () ; } # [doc = " Moves to the next character."] pub (crate) fn bump (& mut self) -> Option < char > { let c = self . chars . next () ? ; # [cfg (debug_assertions)] { self . prev = c ; } Some (c) } # [doc = " Moves to a substring by a number of bytes."] pub (crate) fn bump_bytes (& mut self , n : usize) { self . chars = self . as_str () [n ..] . chars () ; } # [doc = " Eats symbols while predicate returns true or until the end of file is reached."] pub (crate) fn eat_while (& mut self , mut predicate : impl FnMut (char) -> bool) { while predicate (self . first ()) && ! self . is_eof () { self . bump () ; } } pub (crate) fn eat_until (& mut self , byte : u8) { self . chars = match memchr :: memchr (byte , self . as_str () . as_bytes ()) { Some (index) => self . as_str () [index ..] . chars () , None => "" . chars () , } } }
